package io.knowledgebrain.planning;
import java.io.IOException;import java.util.*;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.MeterRegistry;import tools.jackson.databind.json.JsonMapper;
import static io.knowledgebrain.planning.GoalController.*;
@RestController @ConditionalOnProperty(name="brain.planning.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/reminders/{reminderId}/deliveries")
final class ReminderDeliveryController {
 private final ReminderDeliveryStore store;private final SpaceAuthorizationClient authority;private final String origin;private final MeterRegistry metrics;
 private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 ReminderDeliveryController(ReminderDeliveryStore store,SpaceAuthorizationClient authority,@Value("${brain.planning.browser-origin}")String origin,MeterRegistry metrics){this.store=store;this.authority=authority;this.origin=origin;this.metrics=metrics;}
 static String tag(long version){return "\"dp"+version+"\"";}
 static long version(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED);if(h.size()!=1||!h.getFirst().matches("\"dp[1-9][0-9]{0,18}\""))throw ScheduleRules.bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw ScheduleRules.bad();}}
 private UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw ScheduleRules.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN);String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);token=c.getValue();}return authority.authorize(space,token,write?"SCHEDULE_WRITE":"SCHEDULE_READ","PRIVATE",trace);}
 private ResponseEntity<ReminderDeliveryStore.Delivery> response(ReminderDeliveryStore.Delivery v){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(tag(v.version())).body(v);}
 @PostMapping ResponseEntity<ReminderDeliveryStore.Delivery> arm(@PathVariable String spaceId,@PathVariable String reminderId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=ScheduleRules.id(spaceId);var id=ScheduleRules.id(reminderId);String trace=parent(r);var actor=authorize(space,r,true,trace);var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw ScheduleRules.bad();if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE);var bytes=r.getInputStream().readNBytes(1025);if(bytes.length>1024)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE);long version;try{var v=json.readTree(bytes);if(v==null||!v.isObject()||v.size()!=1||!v.path("reminderVersion").isIntegralNumber()||!v.path("reminderVersion").canConvertToLong())throw ScheduleRules.bad();version=v.path("reminderVersion").asLong();if(version<1)throw ScheduleRules.bad();}catch(RuntimeException e){throw ScheduleRules.bad();}var result=store.arm(space,id,actor,version,keys.getFirst(),trace.substring(3,35));var v=result.delivery();metrics.counter("brain.planning.delivery.changes","type",result.replay()?"replayed":"armed").increment();return ResponseEntity.status(result.replay()?200:201).cacheControl(CacheControl.noStore()).eTag(tag(v.version())).header("Location","/api/spaces/"+space+"/reminders/"+id+"/deliveries/"+v.deliveryId()).body(v);}
 @GetMapping ResponseEntity<ReminderDeliveryStore.Page> list(@PathVariable String spaceId,@PathVariable String reminderId,HttpServletRequest r){parameters(r,Set.of("after","limit"));var space=ScheduleRules.id(spaceId);var id=ScheduleRules.id(reminderId);authorize(space,r,false,parent(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(space,id,r.getParameter("after"),(int)number(r.getParameter("limit"),20,100)));}
 @GetMapping("/{deliveryId}") ResponseEntity<ReminderDeliveryStore.Delivery> get(@PathVariable String spaceId,@PathVariable String reminderId,@PathVariable String deliveryId,HttpServletRequest r){parameters(r,Set.of());var space=ScheduleRules.id(spaceId);var reminder=ScheduleRules.id(reminderId);var id=ScheduleRules.id(deliveryId);authorize(space,r,false,parent(r));return response(store.get(space,reminder,id));}
 @DeleteMapping("/{deliveryId}") ResponseEntity<ReminderDeliveryStore.Delivery> cancel(@PathVariable String spaceId,@PathVariable String reminderId,@PathVariable String deliveryId,HttpServletRequest r){parameters(r,Set.of());var space=ScheduleRules.id(spaceId);var reminder=ScheduleRules.id(reminderId);var id=ScheduleRules.id(deliveryId);String trace=parent(r);var actor=authorize(space,r,true,trace);var v=store.cancel(space,reminder,id,actor,version(r),trace.substring(3,35));metrics.counter("brain.planning.delivery.changes","type","cancelled").increment();return response(v);}
 @GetMapping("/{deliveryId}/revisions") ResponseEntity<List<ReminderDeliveryStore.Revision>> history(@PathVariable String spaceId,@PathVariable String reminderId,@PathVariable String deliveryId,HttpServletRequest r){parameters(r,Set.of("before","limit"));var space=ScheduleRules.id(spaceId);var reminder=ScheduleRules.id(reminderId);var id=ScheduleRules.id(deliveryId);authorize(space,r,false,parent(r));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,reminder,id,number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE),(int)number(r.getParameter("limit"),5,10)));}
}
